import{_ as a,o as i,c as l,a2 as r}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"चिकित्सा-गारंटी कानून","description":"","frontmatter":{},"headers":[],"relativePath":"hi/44-医疗保障法.md","filePath":"hi/44-医疗保障法.md"}'),d={name:"hi/44-医疗保障法.md"};function e(o,t,h,n,s,u){return i(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="चिकित्सा-गारंटी-कानून" tabindex="-1">चिकित्सा-गारंटी कानून <a class="header-anchor" href="#चिकित्सा-गारंटी-कानून" aria-label="Permalink to &quot;चिकित्सा-गारंटी कानून&quot;">​</a></h1><table tabindex="0"><thead><tr><th>मद</th><th>सामग्री</th></tr></thead><tbody><tr><td>दस्तावेज़ संख्या</td><td>44</td></tr><tr><td>मॉड्यूल</td><td>कानूनी प्रणाली और शासन-ढाँचा</td></tr><tr><td>कीवर्ड</td><td>चिकित्सा-अधिकार, सहजीवी चिकित्सा, साधना-क्षति उपचार, जीवन-स्वास्थ्य, चिकित्सा-बीमा प्रणाली</td></tr></tbody></table><h2 id="i-विधायी-उद्देश्य-और-मूल-सिद्धांत" tabindex="-1">I. विधायी उद्देश्य और मूल सिद्धांत <a class="header-anchor" href="#i-विधायी-उद्देश्य-और-मूल-सिद्धांत" aria-label="Permalink to &quot;I. विधायी उद्देश्य और मूल सिद्धांत&quot;">​</a></h2><p><em>चिकित्सा-गारंटी कानून</em> लंगर सहजीवी सभ्यता के पाँच सहायक कानूनों में से एक है। इसका उद्देश्य हेंग-ब्रह्मांड के भीतर सभी जीवनों के स्वास्थ्य-अधिकार और चिकित्सा-अधिकार की गारंटी, सभी जातियों को आच्छादित करने वाली सहजीवी चिकित्सा-प्रणाली स्थापित करना, और यह सुनिश्चित करना है कि चोट या बीमारी पर हर जीवन को समय पर, प्रभावी उपचार मिले।</p><p>यह कानून निम्न मूल सिद्धांत स्थापित करता है:</p><table tabindex="0"><thead><tr><th>सिद्धांत</th><th>अर्थ</th></tr></thead><tbody><tr><td>स्वास्थ्य-प्राथमिकता</td><td>जीवन-स्वास्थ्य सभी विकास का आधार है; राज्य और सभ्यता जीवन-स्वास्थ्य की रक्षा को प्राथमिकता देते हैं</td></tr><tr><td>सार्वभौमिक आच्छादन</td><td>चिकित्सा-गारंटी सभी जीवनों को आच्छादित करती है, चाहे जाति, साधना, जन्म या आर्थिक स्थिति कुछ भी हो</td></tr><tr><td>स्तरीकृत उपचार</td><td>आधार-चिकित्सा, क्षेत्रीय-चिकित्सा, उच्च-चिकित्सा त्रिस्तरीय उपचार-प्रणाली स्थापित करना, चिकित्सा-संसाधनों का उचित वितरण</td></tr><tr><td>रोकथाम-उपचार संयोजन</td><td>रोकथाम प्राथमिकता, रोकथाम और उपचार का संयोजन; साधना-क्षति की रोकथाम और पुनर्वास पर ध्यान</td></tr><tr><td>अन्य-जाति अनुकूलन</td><td>विभिन्न जातियों की शारीरिक विशेषताओं हेतु अनुकूलित चिकित्सा-योजनाएँ प्रदान करना; मानव-मानक का एक-आकार-सब-पर लागू करना निषिद्ध</td></tr><tr><td>जनहित-गुण</td><td>आधार चिकित्सा-सेवाओं का जनहित-गुण है; लाभ-उद्देश्य से जीवनों का उपचार-अधिकार नहीं छीना जा सकता</td></tr></tbody></table><h2 id="ii-जीवन-स्वास्थ्य-अधिकार-की-कानूनी-गारंटी" tabindex="-1">II. जीवन-स्वास्थ्य अधिकार की कानूनी गारंटी <a class="header-anchor" href="#ii-जीवन-स्वास्थ्य-अधिकार-की-कानूनी-गारंटी" aria-label="Permalink to &quot;II. जीवन-स्वास्थ्य अधिकार की कानूनी गारंटी&quot;">​</a></h2><p>यह कानून स्पष्ट करता है कि जीवन-स्वास्थ्य अधिकार सहजीवी संविधान द्वारा प्रत्येक जीवन को प्रदत्त मूल अधिकार है, जिसमें विशेष रूप से शामिल:</p><ol><li><strong>आधार चिकित्सा-अधिकार</strong>: प्रत्येक जीवन को निःशुल्क आधार चिकित्सा-सेवाएँ पाने का अधिकार, जिनमें सामान्य रोग-निदान, आधार औषधियाँ, नियमित जाँच आदि शामिल।</li><li><strong>आपात-उपचार अधिकार</strong>: अचानक चोट या बीमारी पर प्रत्येक जीवन को आपात-उपचार पाने का अधिकार; चिकित्सा-संस्थान किसी भी कारण से आपात-उपचार से मना नहीं कर सकते।</li><li><strong>साधना-क्षति उपचार अधिकार</strong>: साधना के दौरान ऊर्जा-विकार, नाड़ी-क्षति, साधना-विचलन जैसी क्षतियाँ झेलने वाले साधकों को व्यावसायिक उपचार पाने का अधिकार।</li><li><strong>सूचित-सहमति अधिकार</strong>: रोगियों को अपनी बीमारी-स्थिति, उपचार-योजना, जोखिम और परिणाम-पूर्वानुमान जानने का, तथा उपचार-योजना चुनने या अस्वीकार करने का अधिकार।</li><li><strong>गोपनीयता-संरक्षण अधिकार</strong>: रोगियों की चिकित्सा-सूचना और शारीरिक डेटा कानून द्वारा संरक्षित; रोगी की सहमति के बिना प्रकटीकरण या अन्य प्रयोजनों में उपयोग नहीं किया जा सकता।</li><li><strong>पुनर्वास-गारंटी अधिकार</strong>: चोट-बीमारी पीड़ितों को पुनर्वास-उपचार और सहायक-उपकरण पाने का अधिकार, जिससे कार्य और जीवन-क्षमताएँ बहाल हों।</li></ol><h2 id="iii-सहजीवी-चिकित्सा-प्रणाली-की-संरचना" tabindex="-1">III. सहजीवी चिकित्सा-प्रणाली की संरचना <a class="header-anchor" href="#iii-सहजीवी-चिकित्सा-प्रणाली-की-संरचना" aria-label="Permalink to &quot;III. सहजीवी चिकित्सा-प्रणाली की संरचना&quot;">​</a></h2><p>लंगर सहजीवी सभ्यता की चिकित्सा-प्रणाली तीन स्तरों में विभाजित है, स्तरों के बीच रेफ़रल और सहयोग तंत्र स्थापित:</p><table tabindex="0"><thead><tr><th>स्तर</th><th>नाम</th><th>कार्य</th><th>आच्छादन-क्षेत्र</th></tr></thead><tbody><tr><td>प्रथम स्तर</td><td>आधार चिकित्सा-केंद्र</td><td>सामान्य रोग-निदान, रोकथाम-स्वास्थ्य, आधार जाँच, आपात-परिवहन</td><td>समुदाय/गाँव/छोटे पटल</td></tr><tr><td>द्वितीय स्तर</td><td>क्षेत्रीय चिकित्सा-केंद्र</td><td>विशेषज्ञ-उपचार, शल्य-उपचार, साधना-क्षति प्रारंभिक उपचार, पुनर्वास</td><td>नगर/क्षेत्र/मध्यम पटल</td></tr><tr><td>तृतीय स्तर</td><td>उच्च चिकित्सा-महासंगठन</td><td>कठिन-गंभीर रोग, उच्च साधना-क्षतियाँ, चेतना-क्षेत्र रोग, अंतर-जातीय कठिन रोग</td><td>सभ्यता-केंद्र/बड़े पटल</td></tr></tbody></table><p>इसके अतिरिक्त, &quot;साधना-क्षति विशेषज्ञता&quot; स्थापित है: साधना के दौरान होने वाली सभी प्रकार की क्षतियों का विशेष उपचार, जिनमें ऊर्जा-अधिभार, नाड़ी-टूटन, हृदय-दानव आक्रमण, आत्मा-आघात आदि शामिल, साधना-नियमों में पारंगत चिकित्सा-कर्मियों से युक्त।</p><h2 id="iv-चिकित्सा-गारंटी-कोष" tabindex="-1">IV. चिकित्सा-गारंटी कोष <a class="header-anchor" href="#iv-चिकित्सा-गारंटी-कोष" aria-label="Permalink to &quot;IV. चिकित्सा-गारंटी कोष&quot;">​</a></h2><p>चिकित्सा-गारंटी कोष सहजीवी चिकित्सा-प्रणाली के संचालन की आर्थिक नींव है, जिसके स्रोतों में शामिल:</p><ul><li>सार्वजनिक संचय विनियोग (मुख्य स्रोत)</li><li>संयुक्त-उत्पादन ठेका तंत्र में चिकित्सा-गारंटी कटौती</li><li>सामाजिक दान</li><li>कोष निवेश-आय</li></ul><p>कोष की भुगतान-सीमा में शामिल: आधार चिकित्सा-सेवा व्यय, आपात-उपचार व्यय, साधना-क्षति उपचार व्यय, आधार औषधि व्यय, पुनर्वास व्यय आदि। रोगियों को केवल थोड़ा स्व-व्यय देना होता है; आर्थिक कठिनाई वालों के लिए छूट और माफ़ी लागू।</p><h2 id="v-चिकित्सा-संस्थान-और-चिकित्सा-कर्मी" tabindex="-1">V. चिकित्सा-संस्थान और चिकित्सा-कर्मी <a class="header-anchor" href="#v-चिकित्सा-संस्थान-और-चिकित्सा-कर्मी" aria-label="Permalink to &quot;V. चिकित्सा-संस्थान और चिकित्सा-कर्मी&quot;">​</a></h2><ul><li><strong>सार्वजनिक चिकित्सा-संस्थान</strong>: राज्य या सभ्यता-समुदाय द्वारा स्थापित, आधार चिकित्सा-सेवाएँ और सार्वजनिक स्वास्थ्य-कार्य वहन, वित्त-पोषण चिकित्सा-गारंटी कोष से सुनिश्चित।</li><li><strong>निजी चिकित्सा-संस्थान</strong>: सामाजिक शक्तियों द्वारा कानूनानुसार स्थापित; उच्च-स्तरीय चिकित्सा-सेवाएँ दे सकते हैं, किंतु चिकित्सा-प्रशासन की निगरानी स्वीकारनी होगी; आपात-रोगियों से मना नहीं कर सकते।</li><li><strong>अन्य-जाति चिकित्सा-संस्थान</strong>: विशेष जातियों की शारीरिक आवश्यकताओं हेतु स्थापित विशेषज्ञ चिकित्सा-संस्थान, अन्य-जाति चिकित्सा-कर्मियों से युक्त।</li><li><strong>चिकित्सा-कर्मियों के अधिकार और दायित्व</strong>: चिकित्सा-कर्मियों को अभ्यास-संरक्षण, उचित पारिश्रमिक, व्यावसायिक प्रशिक्षण जैसे अधिकार मिलते हैं; साथ ही मरणासन्न को बचाने, रोगियों का सम्मान, चिकित्सा-गोपनीयता रखने जैसे दायित्व भी।</li></ul><h2 id="vi-सार्वजनिक-स्वास्थ्य-और-रोकथाम" tabindex="-1">VI. सार्वजनिक स्वास्थ्य और रोकथाम <a class="header-anchor" href="#vi-सार्वजनिक-स्वास्थ्य-और-रोकथाम" aria-label="Permalink to &quot;VI. सार्वजनिक स्वास्थ्य और रोकथाम&quot;">​</a></h2><p>राज्य सार्वजनिक स्वास्थ्य-प्रणाली स्थापित करता है, निम्न कार्य करता है:</p><ol><li>संक्रामक रोग निगरानी और रोकथाम, अंतर-पटल महामारी-पूर्वचेतावनी तंत्र स्थापित करना।</li><li>सभी जीवनों के स्वास्थ्य-जाँच और स्वास्थ्य-अभिलेख प्रबंधन।</li><li>साधना-सुरक्षा प्रचार और साधना-क्षति रोकथाम मार्गदर्शन।</li><li>पर्यावरणीय स्वच्छता और खाद्य-औषधि सुरक्षा निगरानी।</li><li>सार्वजनिक स्वास्थ्य आपात-घटनाओं का आपात-प्रतिक्रिया।</li></ol><h2 id="vii-कानूनी-दायित्व" tabindex="-1">VII. कानूनी दायित्व <a class="header-anchor" href="#vii-कानूनी-दायित्व" aria-label="Permalink to &quot;VII. कानूनी दायित्व&quot;">​</a></h2><p>इस कानून के प्रावधानों का उल्लंघन करने वाले कृत्य परिस्थितियों की गंभीरता के अनुसार निम्न दायित्व वहन करते हैं:</p><ul><li>आपात-रोगियों से मना करने वाले चिकित्सा-संस्थानों पर सुधार-आदेश और जुर्माना; गंभीर परिणाम होने पर अभ्यास-लाइसेंस निरस्त।</li><li>गंभीर लापरवाही से रोगियों को हानि पहुँचाने वाले चिकित्सा-कर्मियों पर क्षतिपूर्ति-दायित्व; गंभीर परिस्थितियों में अभ्यास-योग्यता निरस्त।</li><li>नियम-विरुद्ध शुल्क लेने या अति-चिकित्सा करने वाले चिकित्सा-संस्थानों पर शुल्क-वापसी और जुर्माना।</li><li>रोगियों की चिकित्सा-गोपनीयता प्रकट करने पर मानसिक-क्षति क्षतिपूर्ति; गंभीर परिस्थितियों में आपराधिक दायित्व।</li><li>नकली और घटिया औषधियाँ बनाने-बेचने पर अवैध आय जब्त और जुर्माना; अपराध-गठन पर आपराधिक दायित्व।</li></ul><h2 id="निष्कर्ष" tabindex="-1">निष्कर्ष <a class="header-anchor" href="#निष्कर्ष" aria-label="Permalink to &quot;निष्कर्ष&quot;">​</a></h2><p><em>चिकित्सा-गारंटी कानून</em> लंगर सहजीवी सभ्यता की &quot;हर किसी के लिए मार्ग&quot; दर्शन की स्वास्थ्य-क्षेत्र में अभिव्यक्ति है। सार्वभौमिक-आच्छादित चिकित्सा-गारंटी प्रणाली स्थापित करके, साधना-क्षति विशेषज्ञता बनाकर, आपात-उपचार अधिकार की गारंटी देकर यह सुनिश्चित करता है कि चोट या बीमारी पर हर जीवन को समय पर उपचार मिले, दस हजार जातियों के साझा उन्नयन के लिए ठोस स्वास्थ्य-नींव रखता है।</p><h2 id="संबंधित-दस्तावेज़" tabindex="-1">संबंधित दस्तावेज़ <a class="header-anchor" href="#संबंधित-दस्तावेज़" aria-label="Permalink to &quot;संबंधित दस्तावेज़&quot;">​</a></h2><ul><li>40-共生宪法总纲 (सहजीवी संविधान: सामान्य सिद्धांत)</li><li>38-共生医疗体系 (सहजीवी चिकित्सा-प्रणाली)</li><li>45-住房保障法 (आवास-गारंटी कानून)</li><li>08-人人有路保障体系 (हर किसी के लिए मार्ग गारंटी-प्रणाली)</li></ul>',29)])])}const p=a(d,[["render",e]]);export{c as __pageData,p as default};
